table(['本版工作','结果或边界'],[['真实图像','累计 2114 张照片，其中 230 张用于标定，1884 张用于对照评估'],['材料参数',f"原图 105；本机 HDMI 图像链路 {HC['threshold']}；历史 H264 解码链路 {VC['threshold']}；切换等待产品间隙"],['图片追溯','保存实际帧阈值、参数名称、参数指纹和标定记录指纹'],['实板验收',f"50 张正常或裂纹照片逐像素验证；两段连续运动测试；参数边界切换测试"],['保留旧版本',f"V1.4 原工程保留；{P['records']} 条历史记录复制到 V1.5 并核对内容"]],[3.0,14.0])
p('新工程：D:/Vivado/pynq_z2_tile_v1_5。旧工程：D:/Vivado/pynq_z2_tile_v1_4。新版本没有通过提高像素时钟来掩盖算法问题，也没有让电脑代替 FPGA 做实时检测。')
h('读报告时需要区分的三种证据')
p('离线评估表示电脑运行定点参考模型；硬件一致性表示 FPGA 结果与其实际收到的像素对应；工厂有效性还需要真实相机、照明、运动和缺陷标注。前两项通过，不等于第三项已经通过。')
page('先理解数据怎样经过系统')
p('PYNQ-Z2 上的 Zynq 芯片同时包含 ARM 处理器和可编程逻辑。PS 指处理器系统，适合运行程序和管理网络；PL 指可编程逻辑，可以搭出很多同时工作的运算电路。本项目把像素检测和产品判断放在 PL，ARM 负责调度内存和发送数据。')
p('一帧画面由一行一行的像素组成。HDMI 接收器把高速串行信号还原为彩色像素和同步信号。有效像素标记 DE 表示当前颜色是否属于画面，行同步和场同步帮助电路区分行与帧。检测数据经过流水线后再送往 HDMI 输出和截图缓存。')
table(['术语','在本项目中的含义'],[['流水线','将灰度、邻域比较、区域统计等拆成相邻级。不同像素同时处在不同级，稳定后每个时钟可接收一个新像素。'],['BRAM 与行缓存','FPGA 内部的小容量存储。保留前几行像素，才能在当前像素附近观察二维邻域。'],['DDR','开发板外部的大容量内存，保存完整图像。每帧四字节像素占 1280×720×4=3686400 字节。'],['DMA 与 SG','DMA 是自动搬运数据的硬件。SG 使用预先排好的描述符，告诉它下一帧写到哪个内存槽，不必每帧等 ARM 重新启动。'],['AXI 背压','发送端用有效标记声明数据，接收端用准备标记表示能否接收。HDMI 源不能随意停住，因此来不及接收时必须报告无效帧。'],['ACK 与幂等','ACK 是电脑完成保存后的确认。同一事件重传时保持同一身份；重复确认不应误删下一条事件。'],['时钟与 CDC','各电路可能使用不同频率。CDC 是跨时钟域传递，必须处理采样不同步，不能只靠软件延时。'],['WNS','已约束路径中最差的建立时间余量。非负表示该次实现通过这项检查，不能替代实板和跨时钟检查。']],[3.3,13.7])
p('60 帧/秒、电脑预览速度和截图保存时间是不同指标。PL 每帧都检测，网络只能传走其中一部分完整图像。板端保留最佳证据，电脑保存成功后确认，才允许那块缓存被后续事件复用。')
p('像素时钟跟随 HDMI 输入节拍。当前每秒 60 帧，包含消隐区的标准时序为每行 1650 个时钟、每帧 750 行，因此像素时钟为 1650×750×60=74.25 MHz。只统计有效画面时是 1280×720×60=55.296 百万像素/秒。直接改变这个时钟会改变视频节拍，不能作为修复网络或截图问题的简单开关。')
page('采集间隙、网络取图与存档容量')
p('最初网页上的两个问题来自不同环节：板端事件堆积说明证据产生速度或积压量超过接收；电脑达到 500 条上限又主动暂停接收，进一步放大积压。只提高 HDMI 像素时钟既不能解除软件条数限制，也不能让千兆网无限变快。')
p('V1.4 已将逐次启动的取图方式改为连续 SG DMA。本版继承并重新验证该结构：32 个循环描述符持续安排采集，48 个 DDR 图像槽区分 DMA 正在写、可复用、当前产品最佳图与等待电脑确认的证据。网络读取证据时，DMA 使用其他空闲槽，不需要让输入视频停下来。')
p('当 FPGA 发现同一产品的新候选帧比旧帧更好，调度层替换保留槽；产品离站后形成一个待确认事件。电脑收到图像，核对包信息并完成落盘后才发送 ACK。固件按事件身份释放对应槽，重复 ACK 或旧 ACK 不能错误释放别人的图像。正常预览只抽样读取，不把每一帧都无限堆进事件队列。')
p('电脑端改为可分页查询的 SQLite 存档，不再因为恰好 500 条而停收。原图、掩码和审核信息继续保留，低磁盘空间保护仍会暂停，防止写出不完整记录。取消固定条数上限不是无限容量；需要按磁盘容量规划导出、备份和清理周期。')
p('网页输入帧率改用板端实时帧计数的两秒窗口差分，不再把两次取图完成的短间隔直接当作测量周期，避免网络抖动或旧证据回放造成瞬时虚高。重启编号变化、计数回退和长时间暂停会重置估计。')
h('应观察哪些计数')
table(['计数或指标','含义与本版验收方式'],[['captured','板端成功采集数。对比测试前后增量和实际时间，验证约 60 帧/秒。'],['gaps / invalid','采集间隙和无效帧。运行前后相减，本次两段连续验收要求均为零。'],['dropped / depth','队列满丢弃数与当前待取数量。先保存旧值，再判断本次新增丢失，不能只看历史累计数。'],['host captures','电脑收到的完整图像数；受以太网和文件处理时间限制，通常低于 60 帧/秒。'],['physical identity','结合输入帧码和循环编号重建一次实物通过，检查缺陷产品是否漏存或重复存。']],[5.0,12.0])
p('暂停电脑接收时，FPGA 不会暂停流水线。12 个待确认事件满后仍会丢失并计数。因此正式运行应监测队列和磁盘，长时间停机则先停止上游来料或切换备用存储，不能把有限缓存当作永久录像机。')
page('检测原理与这次改动')
h('从彩色像素得到暗谷特征')
p('每个彩色像素含红、绿、蓝三个 8 位数，范围都是 0 至 255。灰度是亮度的近似值。FPGA 用整数乘加和右移完成计算，不需要浮点处理器。')
eq('Y = floor((77R + 150G + 29B) / 256)')
p('对中心像素，分别观察水平、垂直和两条对角线方向上相距 8 像素的两侧。裂纹常表现为中间暗、两边亮。取两侧较小的亮度，可以抑制只在一侧发生的阶跃边缘；再选四方向中最大的响应。')
eq('S(x,y) = max(0, max_d(min(Y(x+d), Y(x−d)) − Y(x)))')
eq('候选像素 = 有效图像区域内 且 S > T')
p('半径 8 对应 17×17 邻域。行缓存只保留计算所需的邻近行，流水线每个像素时钟接受一个像素。32×32 网格汇总候选像素，并进行邻接区域合并；面积至少 32 像素且长边跨度至少 23 像素的区域才生成框。最多输出 8 个框。')
h('为什么原参数误报而标定参数改善')
p('真实瓷砖表面的深色斑点也会产生暗谷。阈值 36 对干净背景足够，但不能区分强纹理与裂纹。本版用 230 张正常训练照片计算每帧第 32 大的暗谷响应，再取其第 99 百分位的较高离散值，得到 105。数字来自正常样本，不是由程序偷看待检图片的标签决定。')
p('平滑一次、平滑两次和原始暗谷都做过开发比较；平滑未带来更好的漏检表现，因此本版保留已有 PL 数据通路。检测改善来自有证据的参数标定；另在 PL 选帧器中将完整入镜后的居中程度置于候选面积之前，防止纹理或压缩变化使截图偏向边缘。')
h('参数为什么要等一块砖通过再改')
p('FPGA 产生产品号、进入和离开标记。ARM 只根据这些标记判断是否可以提交参数，在产品仍在工位或第一个短暂空帧时继续使用旧参数。留图根据截图自身 config_word 解读阈值，而不是使用网页当前选择值。')
page('产品编号与最佳截图')
p('产品号应对应一块经过工位的实物，而不只是“软件没有出现重复编号”。第一次视频标定后，采集和传输检查通过，但源帧码审计发现 20 个物理缺陷产品生成了 25 个编号，不能算截图功能验收通过。')
p('原因是原来的存在判断只检查画面中央一列。当竖直暗裂纹经过这列时，亮像素数量会跌到门槛以下；连续两个低值帧会被当作产品已经离站，随后又建立新编号。选帧范围被切断后，就容易保存偏离中心的照片。')
p('本版将存在判断改为中央 64 列的亮像素总数，要求平均每列至少 200 个亮像素。720p 检测带有效高度为 500，最大总数为 64×500=32000，仍能用 16 位计数器保存。它只改变触发统计，不平滑用于裂纹检测的图像。')
eq('P = Σ I(R + 2G + B ≥ 320)')
p('求和范围为横坐标 608 至 671、纵坐标 110 至 609。I 是指示函数：括号内条件满足时记 1，否则记 0。')
eq('产品存在条件 P >= 64 × 200 = 12800')
p('针对一条 32 像素宽、贯穿有效高度的暗带，旧单列可能得到零；新触发带仍有 32×500=16000 个亮像素，所以不会把同一块砖拆开。定向 RTL 仿真验证了这个情况，并确认真实空带连续两帧仍能结束产品。')
if (T/'gate_diagnostic.png').exists():picture(T/'gate_diagnostic.png',16.6)
p('图中使用一张实板采回照片做横向位置扫描：单列最低 142，64 列平均最低约 221。这是空间统计曲线，不是伪造的实时波形。新硬件仍需满足单通道、亮瓷砖和暗背景条件。')
p('定时验收还改为等待当前产品自然通过后结束输入，避免直接切为空带导致末尾产品只走了一半。最终审计同时检查源照片与循环次数，验证一块实物只对应一张最佳图，并核对完整性和居中误差。')
page('实际输入链路标定')
p('实板检查发现：硬盘 PNG 与 FPGA 收到的 RGB 并不相同。第一张照片的颜色拟合约为红通道 0.986 倍、绿通道 0.816 倍、蓝通道 0.639 倍，各通道另有约负 0.5 的偏置。这里是实际像素测量，不据此断言某个 Windows 设置一定是原因。')
p('直接使用原图阈值 105 时，50 张静态照片的硬件实现与参考完全一致，但裂纹只报警 13/17，正常图 0/33。首段真实照片运动视频 120 秒没有留下任何报警图，因此该段验收明确失败。完整记录保存在 reports/v15/pre_input_calibration，不能用后续成功覆盖失败事实。')
p('为修复这个问题，我们把官方训练划分的 230 张正常照片逐张通过当前 HDMI 链路采回，再经实际 H264 解码路径采回一次。照片编号放在检测区域外，用于确认取到的帧与来源一致。两次均使用相同的第 32 大响应与第 99 百分位规则，没有利用测试裂纹标签挑选阈值。')
table(['成像空间','正常训练图','阈值'],[['原始 PNG 离线参考','230',105],['本机静态图经 HDMI',HC['normal_training_count'],HC['threshold']],['本机 H264 视频经 HDMI',VC['normal_training_count'],VC['threshold']]],[9.0,4.0,4.0])
p('这 460 次采样仍来自原来的 230 张照片，不能再计为 460 张独立实物。视频标定时短暂保持每张正常照片是为了测量输入链路；正式流水线演示和运动验收仍然匀速通过，不在摄像头下停车。')
p('阈值属于材料、尺度和成像链路的组合。更换电脑色彩设置、视频解码方式、相机、曝光、照明或拍摄距离后都需要重新标定。单纯把原图测试成绩搬到硬件页面，会掩盖实际输入变化。标定不改变 FPGA 算法，也没有让 ARM 或电脑接管实时检测。')
p(f"最终静态实板结果为正常 {H['counts']['good']['alarms']}/33 报警、裂纹 {H['counts']['crack']['alarms']}/17 报警。最终运动源改为预加载照片直接渲染，使用同一图像链路的阈值 {V['threshold']}；76 保留作历史 H264 解码路径对照。对照成功与失败的步骤保留在报告和机器可读证据中。")
page('解决电脑输入端的启动停顿')
p('64 列触发带修复后，真实照片测试已经做到 20 块裂纹产品对应 20 张完整截图，但最初一张偏离中心 178 像素。抽样帧码发现 H264 播放启动时停留数秒，随后跳到后续帧；FPGA 在这期间仍持续采集，不能据此把故障归因于 FPGA 算得慢。该轮失败证据保存在 reports/v15/pre_player_fix。')
p('增加暂停状态的首帧预解码仍未解决这台电脑上的启动异常。本版将默认流水线输入改为预加载纹理：启动时只读取四张瓷砖照片，运行时按统一帧序号计算位置并直接绘制画面。原 MP4 仍保留用于其他播放器和对照研究。')
eq('x = ((n × s − k × 1440 + w) mod 5760) − w')
p('n 是循环中的输入帧号，s 是每帧移动的像素数，k 是第几张纹理，w 是照片宽度。真实照片宽 500，s 为 8，因此目标速度是 8×60=480 像素/秒。高速合成砖宽 560，s 为 32，对应 1920 像素/秒。源码对负数取模作了归一化，使进入和离开画面的位置连续。')
p('位置和帧码使用同一帧号，画面中没有输入源预先画好的缺陷框。生成器既不读取 FPGA 的检测结果，也不执行缺陷识别，因此它属于可重复测试信号源。FPGA 仍负责检测、区域统计、产品编号和最佳证据帧选择。')
p('Windows 的逻辑像素与 HDMI 像素也必须区分。本机缩放比例曾把固定大小的渲染区域放大，造成照片与帧码被裁切；现在用 Viewbox 将完整场景映射到 1280×720。照片先按既定方法缩放并缓存，运动时按整数像素平移，避免每帧重新解码视频。')
p('播放器的状态文件改为写入临时文件后原子替换。读取者只能看到完整的上一份或下一份 JSON；暂时的文件占用只跳过遥测更新，不再导致播放器退出。空白或未完成的命令写入也不会被当作一次停止指令。')
p('本机主屏刷新率高于 HDMI 的 60 Hz，WPF 合成回调会比输入帧更频繁。现在同一输入帧只请求重绘一次，并将这个独立播放器进程设为高于普通优先级，减少重复绘制和调度抖动。运动位置继续由实际经过时间计算，没有通过放慢传送带等待截图。Windows 仍不是实时系统，短暂重复帧和跳帧需要由输入帧码持续监测。')
p('32 像素是本次制定的居中优化目标，不是用户提供的工业精度要求。审计脚本继续保留严格 passed 字段；若超标便返回非零，并另用 functional_pass 表示留图完整性、身份与连续采集是否通过。没有把阈值从 32 改大来制造通过。')
